SELECT p.id AS position_id, e.id AS sig_1m, e.generated_at, e.created_at, e.decision, e.confluence_status, e.confluence_higher_interval, e.confluence_higher_decision, e.confluence_higher_signal_generated_at, e.atr_immediate_entry_allowed, w.execution_reason, w.created_at AS buy_at FROM paper_position p JOIN trade_signal e ON e.id=p.signal_id JOIN wallet_trade w ON w.signal_id=p.signal_id AND w.side='BUY' WHERE p.id IN (123,143,100) ORDER BY p.id LIMIT 10